 auto water=e.evaluate(cold,request(e,cold,{action(s,"water-below-melt","water",.5)}));check(water.stocks()[2].count==Count(3.5,0),"water desorbs below melt from finite independent inventory");check(a::same(water.stocks()[0].mass_kg,cold.stocks[0].mass_kg)&&a::same(water.stocks()[1].mass_kg,cold.stocks[1].mass_kg),"water release retains metal and oxide masses");check(water.evidence()["exposure_after"]["outer_structural_material"]=="oxide"&&water.evidence()["exposure_after"]["bound_adsorbates"].size()==1,"partial water release retains wet oxide exposure");check(a::same(cold.thermal_energy_J-water.thermal_energy(),D(.125)),"binding cost charged once, no melt or latent debit");proof("water-below-melt",water);
 auto dry=e.evaluate(cold,request(e,cold,{action(s,"water-clear","water",4.)}));check(dry.stocks()[2].count.zero()&&a::same(dry.stocks()[1].mass_kg,cold.stocks[1].mass_kg),"complete water release retains oxide");check(dry.evidence()["exposure_after"]["outer_structural_material"]=="oxide"&&dry.evidence()["exposure_after"]["bound_adsorbates"].empty(),"dry oxide is not silently bare metal");proof("dry-oxide-retained",dry);
 auto coveredHot=view(e,1700,true,false);reject([&]{e.evaluate(coveredHot,request(e,coveredHot,{action(s,"buried-metal","metal",1.)}));},"melted metal cannot bypass retained oxide");auto retained=e.evaluate(coveredHot,request(e,coveredHot));check(a::same(retained.stocks()[1].mass_kg,coveredHot.stocks[1].mass_kg),"metal melt alone retains finite oxide stock");proof("melt-with-retained-oxide",retained);
 auto oxideHot=view(e,1300,true,true);reject([&]{e.evaluate(oxideHot,request(e,oxideHot,{action(s,"remove-support","oxide",128.)}));},"oxide support cannot disappear with retained water");auto exposed=e.evaluate(oxideHot,request(e,oxideHot,{action(s,"water-first","water",4.),action(s,"oxide-second","oxide",128.)}));check(exposed.stocks()[2].count.zero()&&a::same(exposed.stocks()[1].mass_kg,D(0.)),"explicit ordered water and oxide removal debits both finite pools");check(exposed.evidence()["exposure_after"]["outer_structural_material"]=="metal","explicit oxide depletion exposes next retained material");proof("explicit-exposure-transition",exposed);
 auto dryHot=view(e,1300,true,false);auto partial=e.evaluate(dryHot,request(e,dryHot,{action(s,"partial-oxide","oxide",64.)}));check(a::same(partial.stocks()[1].mass_kg,D(.0625))&&partial.evidence()["exposure_after"]["outer_structural_material"]=="oxide","partial oxide loss retains oxide exposure");proof("partial-oxide",partial);
 auto melt=view(e,1700,false,false);auto meltHash=e.view_sha256(melt);try{e.evaluate(melt,request(e,melt,{action(s,"no-energy-at-melt","metal",1.)}));check(false,"melt alone must not remove material");}catch(const a::BudgetRefusal&r){check(a::same(D::read(r.evidence["available_J"]),D(0.)),"melt alone has zero incremental removal allowance");refusals.push_back(r.evidence);}check(e.view_sha256(melt)==meltHash,"failed melt proposal changes no mass or energy");
 auto budget=melt;budget.thermal_energy_J=budget.thermal_energy_J+D(128.);auto small=e.evaluate(budget,request(e,budget,{action(s,"small-metal-plan","metal",1.)}));check(a::same(small.stocks()[0].mass_kg,D(1.)-D(std::ldexp(1.,-10))),"explicit partial metal plan fits energy budget");check(small.evidence()["final_projected_T_K"].get<double>()>=1700&&small.evidence()["final_projected_T_K"].get<double>()<=1800,"remaining material temperature derives from current mass and E");proof("partial-metal-ablation",small);
 auto tooBig=request(e,budget,{action(s,"over-budget","metal",4.)});auto savedWeight=tooBig.actions[0].carriers[0].weight;try{e.evaluate(budget,tooBig);check(false,"overbudget must refuse");}catch(const a::BudgetRefusal&r){check(D::read(r.evidence["available_J"]).compare(D::read(r.evidence["requested_incremental_J"]))<0,"exact allowance quote shows insufficient budget");check(tooBig.actions[0].carriers[0].weight==savedWeight&&e.view_sha256(budget)==tooBig.expected_view_sha256,"refusal does not shrink packet weight or mutate external trial");refusals.push_back(r.evidence);}
 auto atBudget=melt;atBudget.thermal_energy_J=atBudget.thermal_energy_J+D(128.);reject([&]{e.evaluate(atBudget,request(e,atBudget,{action(s,"K-is-extra","metal",2.,{100,0,0})}));},"actual sampled K participates in removal budget");auto moving=e.evaluate(budget,request(e,budget,{action(s,"actual-K","metal",1.,{100,0,0})}));proof("actual-K-reference-and-support",moving);check(!a::same(D::read(moving.evidence()["support_impulse_N_s"][0]),D(0.)),"actual proper momentum gives fixed support impulse quote");
 auto extra=action(s,"owned-other-transfer","metal",1.);extra.other_energy_out_J=D(1.);extra.other_energy_owner="manufactured-fracture-owner";auto other=e.evaluate(budget,request(e,budget,{extra}));proof("identified-other-outward-transfer",other);
 auto endpoint=view(e,1800,false,false);endpoint.thermal_energy_J=endpoint.thermal_energy_J+D(std::numeric_limits<double>::denorm_min());reject([&]{e.evaluate(endpoint,request(e,endpoint));},"exact subULP hot-range overrun refused without clamp");auto low=view(e,298.2,false,false);auto lowProof=e.evaluate(low,request(e,low));check(lowProof.thermal_energy().compare(D(0.))<0,"negative cold reference energy remains valid");proof("negative-cold-reference",lowProof);
 auto tiny=cold;tiny.stocks[2].count=Count(1.,-1e-20);auto tinyr=request(e,tiny,{action(s,"third-residual","water",1e-100)});auto tinyHash=e.view_sha256(tiny);reject([&]{e.evaluate(tiny,tinyr);},"lossy Count2 source-pool export refused despite exact gas count support");check(e.view_sha256(tiny)==tinyHash,"source-pool refusal preserves common snapshot");
 for(int mutation=0;mutation<13;++mutation){auto bad=scenario();switch(mutation){case 0:bad.models[0].trigger_K.reset();break;case 1:bad.models[0].removal_J_kg_excluding_actual_K.reset();break;case 2:bad.models[0].product_R_J.reset();break;case 3:bad.models[0].reference_density_kg_m3.reset();break;case 4:bad.models[0].reference_id="other-zero";break;case 5:bad.models[0].removal_J_kg_excluding_actual_K=131072.;break;case 6:bad.models[2].trigger=a::Trigger::MeltBudget;bad.models[2].trigger_K=1700;break;case 7:bad.models[0].product_charge_e=1;break;case 8:bad.models[1].product_elements={{"M_proxy",1.}};break;case 9:bad.stationary_fixed_support=false;break;case 10:bad.models[2].source_Tmax.reset();break;case 11:bad.condensed_order={"metal"};break;case 12:bad.models[0].product_mass_kg=1.;break;}reject([&]{a::Evaluator badEval(bad);},"missing/inconsistent explicit material/reference/trigger input "+std::to_string(mutation));}
 for(int mutation=0;mutation<11;++mutation){auto v=cold;auto r=request(e,v,{action(s,"request-check","water",.5)});switch(mutation){case 0:r.expected_view_sha256=a::hash("stale");break;case 1:r.expected_exposure_sha256=a::hash("foreign");break;case 2:r.actions.push_back(r.actions[0]);break;case 3:r.actions[0].carriers[0].weight=0;break;case 4:r.actions[0].carriers[0].kinetic_per_unit_J=1.;break;case 5:r.actions[0].other_energy_out_J=D(1.);break;case 6:v.end_s=v.begin_s;break;case 7:v.stocks[2].mass_kg=D(1.);break;case 8:v.consumed_event_ids.insert("request-check");r=request(e,v,r.actions);break;case 9:r.actions[0].carriers[0].weight=5.;break;case 10:v.stocks[1].mass_kg=D(0.);break;}auto old=e.view_sha256(v);reject([&]{e.evaluate(v,r);},"stale/malformed finite-inventory proposal "+std::to_string(mutation));check(e.view_sha256(v)==old,"refusal leaves external trial unchanged "+std::to_string(mutation));}
