 auto cumulative=melt;cumulative.thermal_energy_J=cumulative.thermal_energy_J+D(80.);auto cumulativeHash=e.view_sha256(cumulative);try{e.evaluate(cumulative,request(e,cumulative,{action(s,"first-affordable","metal",1.),action(s,"second-unaffordable","metal",1.)}));check(false,"second action must use remaining energy");}catch(const a::BudgetRefusal&r){check(D::read(r.evidence["available_J"]).compare(D::read(r.evidence["requested_incremental_J"]))<0,"sequential action uses diminished local energy budget");refusals.push_back(r.evidence);}check(e.view_sha256(cumulative)==cumulativeHash,"late action refusal publishes none of the earlier actions");
